"""Rebuild native libraries and rerun the offline project evaluation."""
import argparse,subprocess,sys,platform,time,json
from pathlib import Path
from main import ROOT,write_json,wav_bytes,seal_wav,unseal_wav

def summary():
    results=ROOT/'results'
    b=json.loads((results/'benchmark.json').read_text());e=json.loads((results/'experiments.json').read_text());q=json.loads((results/'audio_metrics.json').read_text());net=json.loads((results/'network_simulation.json').read_text())
    lines=['# Measured host results','',f'Platform: {b["platform"]}. See `environment.json` for versions.','',b['method'],'','## Audio reconstruction','',f'MSE = {q["MSE"]}; PSNR = {q["PSNR_dB"]}; SNR = {q["SNR_dB"]}; exact sample fraction = {q["exact_sample_fraction"]}. Source: two-second synthetic 8 kHz mono chirp, not a microphone recording.','', '![Original and recovered audio](audio_analysis.png)','', '## Native implementation benchmark','', '| Cipher | Frame ms | Payload B | Encrypt median µs | Decrypt median µs | Encrypt p95 µs | MiB/s |', '|---|---:|---:|---:|---:|---:|---:|']
    for r in b['rows']:lines.append(f'| {r["cipher"]} | {r["frame_ms"]} | {r["payload_bytes"]} | {r["enc_median_us"]:.3f} | {r["dec_median_us"]:.3f} | {r["enc_p95_us"]:.3f} | {r["throughput_MiB_s"]:.2f} |')
    lines+=['','![Benchmark](benchmark.png)','','200 measured trials per row, 5 warmups. Both ciphers cycle through the same WAV frames. Timing includes ctypes overhead. Raw timings are in benchmark_raw.json; scheduling/outliers are not concealed. Ascon was faster in these host measurements. These are not ESP32, energy or production-performance claims. Packet overhead is 44 bytes for both algorithms, excluding transport headers.','', '## Screening statistics','',f'- State avalanche mean: {e["avalanche_mean"]*100:.3f}%; sampled range {e["avalanche_min"]*100:.3f}–{e["avalanche_max"]*100:.3f}% over {e["trials"]} trials.',f'- Key sensitivity mean: {e["key_sensitivity_mean"]*100:.3f}%.',f'- Empirical ciphertext byte entropy over 65,536 bytes: {e["ciphertext_byte_entropy_65536"]:.6f} bits/byte.',f'- Exact rotation equivalence: {e["rotation_equivariance_matches_of_32"]}/32 sampled pairs.',f'- Distinct output words for five repeated-word states: {e["repeated_word_output_distinct_words"]}.','', '| Rounds | Mean changed output bits (%) |','|---:|---:|']
    for r,x in e['diffusion_by_round'].items():lines.append(f'| {r} | {100*x:.3f} |')
    lines+=['','No duplicate sampled output differences were found in this run. That observation is not a differential attack bound. Simple screens did not expose a functional defect requiring a change to the supplied round function. The raw F has rotation/cyclic-word symmetry; constants break tested exact symmetries but unexamined weaknesses remain. No security conclusion follows from the scores.','', '## Simulated network loss','',f'Seed {net["seed"]}: {net["received"]}/{net["frames"]} frames received; {net["concealed_frames"]} replaced by silence; {net["late_frames"]} late. Requested loss probability {net["loss_probability"]}, maximum injected jitter {net["max_injected_jitter_ms"]} ms.',f'Recovery PSNR with loss: {net["quality"]["PSNR_dB"]:.3f} dB; SNR {net["quality"]["SNR_dB"]:.3f} dB. This is simulation, not measured Wi-Fi loss.','', '## Code and memory evidence','', 'The compiler `size` output in native_object_size.txt reports 3,585 bytes for the CAALC object and 13,782 for upstream reference Ascon on this host build. GNU text size includes code/read-only sections; it is not total ESP32 flash. CAALC includes an inverse-permutation API not used in live audio. These figures depend on source variant, architecture, inlining and compiler.','', 'The .su files contain compiler per-function stack estimates, not whole-call-chain peak RAM. CAALC state is 48 bytes plus temporaries; Ascon state is 40 bytes plus temporaries. Neither implementation allocates a heap buffer in its core API; caller input/output buffers and Python/FFI/SDK memory are separate. No physical ESP32 RAM, flash, execution, latency or power measurement is claimed.']
    large=results/'large_caalc_audio.json'
    if large.exists():
        d=json.loads(large.read_text());lines+=['','## Large custom-cipher audio test','',f'A {d["pcm_bytes"]:,}-byte PCM recording ({d["duration_seconds"]} seconds at 8 kHz) passed exact CAALC file reconstruction with {d["frame_ms"]} ms frames. Python reference encryption took {d["encrypt_seconds"]:.3f} s and decryption {d["decrypt_seconds"]:.3f} s on this shared host. This is separate from the native benchmark and includes file/container work.']
    (results/'RESULTS.md').write_text('\n'.join(lines)+'\n')

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--summary-only',action='store_true');p.add_argument('--large',action='store_true');a=p.parse_args()
    if not a.summary_only:
        for command in ([sys.executable,'build_native.py'],[sys.executable,'main.py','demo'],[sys.executable,'main.py','mlkem'],[sys.executable,'main.py','experiments'],[sys.executable,'main.py','benchmark','results/original.wav','--trials','200']):subprocess.run(command,cwd=ROOT,check=True)
        with (ROOT/'results/pytest.txt').open('w') as f:subprocess.run([sys.executable,'-m','pytest','tests','-q'],cwd=ROOT,stdout=f,stderr=subprocess.STDOUT,check=True)
    if a.large:
        raw=wav_bytes(8000,bytes(range(256))*4096);key=bytes(range(16));start=time.perf_counter();c=seal_wav(raw,key,40);middle=time.perf_counter();r=unseal_wav(c,key);end=time.perf_counter();assert r==raw
        write_json(ROOT/'results/large_caalc_audio.json',{'pcm_bytes':1048576,'duration_seconds':65.536,'frame_ms':40,'exact_recovery':True,'encrypt_seconds':middle-start,'decrypt_seconds':end-middle})
    summary();print('Results summary written. Physical hardware status is not changed by this script.')
